import * as zod from "zod";
import { AgentCreatorResource } from "./agentCreatorResource.zod.js";
import { AgentRuntime } from "./agentRuntime.zod.js";
import { ApprovalMode } from "./approvalMode.zod.js";
import { LastTurnResource } from "./lastTurnResource.zod.js";
import { PendingActionResource } from "./pendingActionResource.zod.js";
import { ReasoningEffort } from "./reasoningEffort.zod.js";
import { SubagentCountResource } from "./subagentCountResource.zod.js";
import { ThreadStatus } from "./threadStatus.zod.js";
import { TodoResource } from "./todoResource.zod.js";

export const AgentResource = zod
  .strictObject({
    id: zod.string(),
    slug: zod.string().describe("Unique handle within the project, used in `@slug` mentions."),
    name: zod.string(),
    description: zod.string(),
    instructions: zod.string(),
    runtime: AgentRuntime,
    serviceAccountId: zod.string().describe("The IAM service account user id this agent acts as."),
    machineId: zod
      .string()
      .nullable()
      .describe("The Fleet machine this agent is locked to. Null when unbound."),
    machineSudo: zod
      .boolean()
      .describe(
        "Whether the agent's service account holds administrative sudo access on `machineId`.",
      ),
    threadId: zod.string().describe("The single conversation thread belonging to this agent."),
    modelId: zod.string(),
    reasoningEffort: zod.union([ReasoningEffort, zod.null()]),
    approvalMode: ApprovalMode,
    status: ThreadStatus,
    activity: zod.string().nullable(),
    recentMessage: zod.string().nullable(),
    unread: zod.boolean(),
    todos: zod.array(TodoResource),
    pendingAction: zod.union([PendingActionResource, zod.null()]),
    subagents: SubagentCountResource,
    lastTurn: zod.union([LastTurnResource, zod.null()]),
    creator: zod
      .union([AgentCreatorResource, zod.null()])
      .describe(
        "Who created this agent and via which channel (`console`, `companion`, or `plan`). Null when unknown.",
      ),
    createdAt: zod.iso.datetime({ offset: true }),
    updatedAt: zod.iso.datetime({ offset: true }),
  })
  .describe(
    "A resident project agent with a dedicated service account and single living main thread.",
  );

export type AgentResource = zod.input<typeof AgentResource>;
export type AgentResourceOutput = zod.output<typeof AgentResource>;
